mapper.select:
SELECT t.* FROM (SELECT anm.*, tt.unit_name, tt.name, cc.contract_number payment_number, (select faam.attachment_id from fnd_atm_attachment_multi faam where faam.table_pk_value = anm.notice_manage_id and faam.table_name = 'AST_NOTICE_MANAGE') attachment_id, (SELECT pp.contract_number FROM PRJ_PROJECT PP WHERE pp.project_id = cc.project_id) contract_number, (select h.bp_name from hls_bp_master h where h.bp_id = cc.tenant_id) bp_name, (select c.times from con_contract_cashflow c where c.cashflow_id = anm.cashflow_id) times, (select c.cf_item from con_contract_cashflow c where c.cashflow_id = anm.cashflow_id) cf_item, (select c.due_date from con_contract_cashflow c where c.cashflow_id = anm.cashflow_id) due_date, (select c.calc_date from con_contract_cashflow c where c.cashflow_id = anm.cashflow_id) calc_date, (select c.fine_days from con_contract_cashflow c where c.cashflow_id = anm.cashflow_id) fine_days, (select c.write_off_flag from con_contract_cashflow c where c.cashflow_id = anm.cashflow_id) write_off_flag, (select c.CF_DIRECTION from con_contract_cashflow c where c.cashflow_id = anm.cashflow_id) CF_DIRECTION, (select t.templet_name from hls_doc_file_templet t where t.templet_id = anm.templet_id) templet_name, (select t.templet_code from hls_doc_file_templet t where t.templet_id = anm.templet_id) templet_code, (SELECT CASE WHEN c.WRITE_OFF_FLAG = 'FULL' THEN '完全核销' WHEN c.WRITE_OFF_FLAG = 'PARTIAL' THEN '部分核销' ELSE '未核销' END from con_contract_cashflow c where c.cashflow_id = anm.cashflow_id) WRITE_OFF_FLAG_DESC, (select hci.description from con_contract_cashflow c, hls_cashflow_item hci where c.cashflow_id = anm.cashflow_id and hci.CF_ITEM = c.CF_ITEM) cf_project, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code_value = anm.notice_type and v.code = 'AST008.NOTICE_TYPE') as notice_type_desc, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code_value = anm.print_status and v.code = 'AST.PRINT_STATUS') as print_status_desc FROM AST_NOTICE_MANAGE anm left join con_contract cc on cc.contract_id = anm.contract_id left join (SELECT FE.NAME, SUA.USER_ID, MIN(FOU.UNIT_NAME) UNIT_NAME, SUA.COMPANY_ID FROM SYS_USER_ALLOCATION SUA LEFT JOIN FND_EMPLOYEE_ASSIGNS FEA ON SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID LEFT JOIN FND_ORG_UNIT FOU ON FEA.UNIT_ID = FOU.UNIT_ID, (SELECT MIN(COMPANY_ID) COMPANY_ID, USER_ID FROM SYS_USER_ALLOCATION GROUP BY USER_ID ORDER BY USER_ID ASC) SUAC, FND_EMPLOYEE FE WHERE SUA.COMPANY_ID = FEA.COMPANY_ID AND SUA.COMPANY_ID = FOU.COMPANY_ID AND SUA.COMPANY_ID = SUAC.COMPANY_ID AND SUA.USER_ID = SUAC.USER_ID AND FE.EMPLOYEE_ID = FEA.EMPLOYEE_ID GROUP BY SUA.USER_ID, SUA.COMPANY_ID, FE.NAME ORDER BY SUA.USER_ID ASC) tt on tt.user_id = anm.user_id ) t
T.NOTICE_MANAGE_ID = #{noticeManageId}
AND T.NOTICE_MANAGE_ID IN
#{item}
AND T.CONTRACT_ID = #{contractId}
and T.contract_number like '%'||#{contractNumber}||'%'
AND T.TIMES = #{times}
AND T.NOTICE_TYPE = #{noticeType}
AND T.DUE_DATE >= #{dueDateStart}
AND T.DUE_DATE <= #{dueDateEnd}
AND T.write_off_flag = #{writeOffFlag}
AND T.print_status = #{printStatus}
AND T.print_status != #{disPrintStatus}
AND T.BP_NAME like concat(concat('%',#{bpName}),'%')
AND T.CF_PROJECT LIKE '%'|| #{cfProject,jdbcType=VARCHAR}||'%'
AND T.name LIKE '%'|| #{name,jdbcType=VARCHAR}||'%'
AND T.unit_name LIKE '%'|| #{unitName,jdbcType=VARCHAR}||'%'
order by t.NOTICE_MANAGE_ID desc

SELECT t1.* FROM (SELECT t.contract_id, t.cashflow_id, (SELECT c.contract_number FROM con_contract c WHERE c.contract_id = t.contract_id) contract_number, (SELECT c.contract_name FROM con_contract c WHERE c.contract_id = t.contract_id) contract_name, (select p.approval_number from prj_project p,con_contract c where p.project_id = c.project_id and c.contract_id = t.contract_id)approval_number, t.times, t.due_date, t.due_amount, t.cf_item, t.cf_type, t.calc_date, t.fine_days, t.write_off_flag, CASE WHEN t.WRITE_OFF_FLAG = 'FULL' THEN '完全核销' WHEN t.WRITE_OFF_FLAG = 'PARTIAL' THEN '部分核销' ELSE '未核销' END WRITE_OFF_FLAG_DESC, (SELECT i.description FROM hls_cashflow_item i WHERE i.cf_item = t.cf_item AND i.cf_type = t.cf_type) cf_project, (SELECT c.tenant_id FROM con_contract c WHERE c.contract_id = t.contract_id) bp_id, (SELECT bp.bp_name FROM con_contract c, hls_bp_master bp WHERE c.contract_id = t.contract_id AND c.tenant_id = bp.bp_id) bp_name, (SELECT bp.bp_name FROM con_contract c, hls_bp_master bp WHERE c.contract_id = t.contract_id AND c.tenant_id = bp.bp_id) sending_object FROM con_contract_cashflow t,con_contract c where c.contract_id = t.contract_id and c.data_class = 'NORMAL') t1 WHERE 1 = 1
and t1.contract_id = #{contractId}
and t1.bp_name like concat('%',concat(#{bpName},'%'))
and t1.contract_number like concat('%',concat(#{contractNumber},'%') )
and t1.cf_item = #{cfItem}
and t1.cf_project like concat('%',concat(#{cfProject},'%'))
and t1.times = #{times}
order by t1.contract_number,t1.times

select a.templet_code, a.templet_id, a.templet_name, a.templet_type
from hls_doc_file_templet a

    a.enabled_flag = 'Y'
    and a.templet_code like concat('PLM_NOTICE_PRINT_',concat(#{templetNameStr},'%'))


        and a.templet_code = #{templetCode}



        and a.templet_name = #{templetName}

SELECT t1.* FROM (SELECT hci.cf_item, hci.description cf_project FROM hls_cashflow_item hci) t1
1=1
and t1.cf_item = #{cfItem}
and t1.cf_project = #{cfProject}
order by t1.cf_item
